 selects=[('mode', T('평가 방식', 'Grading'), [('rel', T('상대평가 (순위)', 'Relative (rank)')), ('abs', T('절대평가 (합격선 고정)', 'Absolute (fixed pass line)'))], 'rel', T('결과를 순위로 볼지, 고정된 합격선을 넘을 가능성으로 볼지 골라요', 'Choose whether the result is a rank or the chance of clearing a fixed pass line'))],
